const $ = id => document.getElementById(id);
const motion = window.CiteMotion || new Proxy({}, {get: () => () => {}});
let scenarios = {};
let uploadedCorpus=false, uploading=false, uploadTimer, sessionToken, corpusHash;
let bertEvents=0, bertServed=0, bertFallbacks=0, bertConfidence=[];
let socket, sessionId, selected='messy', turnId, ended=false, debounce, busy=false, epoch=0, seq=0, lastEvent=null, audit=[], currentClaims=[], pending=new Map(), streamOrigin=performance.now();
function node(tag, cls, text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function error(message){$('error').textContent=message;$('error').hidden=!message;}
function newTurn(){turnId=crypto.randomUUID();ended=false;lastEvent=null;}
function controls(){const disabled=busy||socket?.readyState!==WebSocket.OPEN;for(const id of ['commit','bullets'])$(id).disabled=disabled;$('replay').disabled=disabled||uploadedCorpus||!scenarios[selected];$('upload-open').disabled=disabled;$('upload-apply').disabled=uploading;$('benchmark-run').disabled=disabled||!uploadedCorpus||!$('benchmark-file').files.length;$('question').disabled=busy;document.querySelectorAll('.claim-controls .text-button').forEach(b=>b.disabled=disabled);document.querySelectorAll('.scenario').forEach(b=>b.disabled=disabled||uploadedCorpus||!scenarios[b.dataset.scenario]);}

function connect(){
 const generation=++epoch;clearTimeout(debounce);socket?.close();audit=[];pending.forEach(x=>{clearTimeout(x.timeout);x.reject(new Error('Session reset'));});pending.clear();newTurn();streamOrigin=performance.now();
 socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/stream`);
 $('connection').textContent='Connecting';$('connection-dot').className='';controls();
 socket.onmessage=event=>{if(generation!==epoch)return;const data=JSON.parse(event.data);
  if(data.type==='corpus_loaded'){clearTimeout(uploadTimer);uploading=false;uploadedCorpus=true;sessionToken=data.session_token;corpusHash=data.corpus_hash;sessionId=data.session_id;clearWorkspace();audit=[];newTurn();$('session-label').textContent=`Session ${sessionId.slice(0,8)} · memory only`;$('upload-status').textContent=`Loaded ${data.documents} documents and ${data.chunks} passages. Add a matching benchmark to measure it.`;$('organizer-score').textContent='Not run';$('organizer-score-note').textContent=`${data.documents} docs · ${data.chunks} passages`;$('benchmark-details').replaceChildren();$('corpus-title').textContent='Organizer corpus';$('corpus-summary').textContent=`${data.documents} documents · ${data.chunks} passages · this session only`;$('corpus-footer').textContent='Organizer corpus · not benchmarked';$('corpus-dialog-note').textContent='Organizer documents in this session only.';$('question').placeholder='Ask about the documents you uploaded…';$('upload-dialog').close();controls();return;}
  if(data.type==='ready'){sessionToken=data.session_token;corpusHash=data.corpus_hash;sessionId=data.session_id;$('session-label').textContent=`Session ${sessionId.slice(0,8)} · memory only`;$('connection').textContent='Local session';$('connection-dot').className='connected';$('backend').textContent=`${data.backend==='dense'?'Local MiniLM + BM25 + reranking':'Lightweight lexical RRF'} · ${data.parser}`;const active=data.parser.startsWith('auto:')||data.parser.startsWith('bert:');$('bert-score').textContent=active?'BERT active':'Fallback parser';$('bert-score-note').textContent=data.parser;controls();return;}
  if(data.type==='benchmark_result'){busy=false;$('organizer-score').textContent=`${data.passed}/${data.total}`;$('organizer-score-note').textContent=`${data.citation_support.supported}/${data.citation_support.emitted} supported · ${data.fabricated_ids} fabricated IDs`;$('upload-status').textContent=data.disclosure;$('benchmark-details').replaceChildren(...data.cases.map(row=>{const item=node('div',`benchmark-row ${row.pass?'':'fail'}`,`${row.pass?'PASS':'FAIL'} · ${row.id} · ${row.question} · cited: ${row.actual_citations.join(', ')||'none'}`);return item;}));motion.claims(Array.from($('benchmark-details').children));controls();return;}
  if(data.type==='error'){if(uploading){clearTimeout(uploadTimer);uploading=false;busy=false;$('upload-status').textContent=data.detail;controls();}error(data.detail);const matching=data.event_id?[[data.event_id,pending.get(data.event_id)]]:[...pending];matching.forEach(([id,x])=>{if(x){clearTimeout(x.timeout);x.reject(new Error(data.detail));pending.delete(id);}});return;}
  render(data);const waiter=pending.get(data.event_id);if(waiter){clearTimeout(waiter.timeout);waiter.resolve(data);pending.delete(data.event_id);}
 };
 socket.onclose=()=>{if(generation!==epoch)return;if(uploading){clearTimeout(uploadTimer);uploading=false;busy=false;$('upload-status').textContent='Connection closed. The upload was not retained.';}$('connection').textContent='Disconnected';$('connection-dot').className='';controls();pending.forEach(x=>{clearTimeout(x.timeout);x.reject(new Error('Connection closed'));});pending.clear();};
 socket.onerror=()=>{if(generation===epoch)error('Connection failed. Check the local server, then start a new session.');};
}
function send(text,final=false,extra={}){
 if(socket?.readyState!==WebSocket.OPEN)return Promise.reject(new Error('Server is disconnected'));
 if(!text.trim())return Promise.reject(new Error('Enter a question first.'));
 if(ended)newTurn();const event_id=`event-${++seq}`;
 const message={event_id,turn_id:turnId,sequence:seq,text,timestamp_ms:Math.round(performance.now()-streamOrigin),is_final:final,...extra};lastEvent=event_id;if(final)ended=true;
 return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{pending.delete(event_id);reject(new Error('Response timed out. Start a new session to retry.'));},60000);pending.set(event_id,{resolve,reject,timeout});socket.send(JSON.stringify(message));});
}
function trace(events){for(const e of events){audit.push(e);const payload=e.payload;const li=node('li');li.append(node('span','mono',`${e.timestamp_s.toFixed(1)}s`),node('strong','',e.event_type.replaceAll('_',' ')),node('span','',payload.reason||payload.query||(payload.selected_chunk_id?`Verified ${payload.selected_chunk_id}`:payload.revision_of?`Replaced ${payload.revision_of}`:payload.elapsed_ms!==undefined?`${payload.elapsed_ms} ms · ${payload.backend}`:payload.verification?`${payload.verification} · ${(payload.citations||[]).join(', ')||'no supported citation'}`:payload.version?`Version ${payload.version} · ${(payload.replaced||[]).length} replaced · ${(payload.preserved||[]).length} preserved`:payload.candidate_chunk_ids?`${payload.candidate_chunk_ids.length} candidate passages`:payload.intents?`${payload.intents.length} intents · ${payload.method}`:payload.discarded_candidates!==undefined?`${payload.discarded_candidates} tentative candidates invalidated`:'Recorded')));$('timeline').prepend(li);motion.trace(li);}while($('timeline').children.length>60)$('timeline').lastChild.remove();}
function inspect(claim,reveal=true){if(reveal)document.body.classList.add('source-open');const e=claim.evidence[0];if(!e)return;$('evidence').replaceChildren();$('source-state').textContent='Committed evidence';$('evidence').append(node('blockquote','quote',`“${e.text}”`));const dl=node('dl','source-meta');for(const [k,v] of [['Document',e.doc_id],['Section',e.section],['Evidence ID',e.chunk_id],['Retrieval',claim.evidence_event_ids.join(', ')],['Source',e.metadata.source||'Supplied corpus'],['Offsets',`${e.metadata.start||0}–${e.metadata.end||e.text.length} in normalized document`]])dl.append(node('dt','',k),node('dd','',v));$('evidence').append(dl,node('p','verified','Exact source-text match · Citation belongs to the evidence retrieved for this claim.'));motion.evidence();
}
function renderClaims(claims,changed,bullets=false){const previous=new Map(currentClaims.map(c=>[c.claim_id,c]));currentClaims=claims;$('answer').replaceChildren();claims.forEach((c,index)=>{const article=node('article',`claim ${c.citations.length?'':'uncertain'}`);article.dataset.claimId=c.claim_id;const label=node('div','claim-label');label.append(node('span','',c.citations.length?'SOURCE-SUPPORTED EXTRACT':'INSUFFICIENT EVIDENCE'),node('span','',!previous.has(c.claim_id)?'New':changed.includes(c.claim_id)?'Updated':'Unchanged'));article.append(label,node('p','',`${bullets?'• ':''}${c.text}`));if(changed.includes(c.claim_id)&&previous.has(c.claim_id)&&previous.get(c.claim_id).text!==c.text){const diff=node('details','claim-diff');diff.append(node('summary','','View previous wording'),node('p','',previous.get(c.claim_id).text));article.append(diff);}const actions=node('div','claim-controls');if(c.citations.length){const cite=node('button','citation',c.citations[0]);cite.onclick=()=>inspect(c);actions.append(cite);}const refine=node('button','text-button','Refine this claim');refine.onclick=()=>{if(article.querySelector('form'))return;const form=node('form','refine-form');const input=node('input');input.placeholder='Add a constraint, e.g. liquid damage';input.setAttribute('aria-label','New constraint for this claim');input.required=true;const go=node('button','secondary','Apply targeted refinement →');form.append(input,go);form.onsubmit=async event=>{event.preventDefault();clearTimeout(debounce);busy=true;controls();try{newTurn();$('question').value=input.value;await send(input.value,true,{target_intent_key:c.intent_key});}catch(e){error(e.message);}finally{busy=false;controls();}};article.append(form);input.focus();};actions.append(refine);article.append(actions);$('answer').append(article);});motion.claims(Array.from($('answer').children));$('answer-actions').hidden=!claims.length;if(claims.some(c=>c.evidence.length))inspect(claims.find(c=>c.evidence.length),false);else{$('evidence').replaceChildren(node('p','muted','No verified source passage was selected for this question.'));$('source-state').textContent='No citation';}}
function render(data){if(data.duplicate)return;trace(data.retrieval_events);for(const event of data.retrieval_events){const diagnostic=event.event_type==='intents_decomposed'&&event.payload.decomposer_diagnostic;if(!diagnostic)continue;bertEvents++;bertServed+=diagnostic.served==='bert';bertFallbacks+=diagnostic.served!=='bert';if(diagnostic.min_confidence!==null&&diagnostic.min_confidence!==undefined)bertConfidence.push(diagnostic.min_confidence);const confidence=bertConfidence.length?`${(100*Math.min(...bertConfidence)).toFixed(1)}% min confidence`:'confidence unavailable';$('bert-score').textContent=`${bertServed}/${bertEvents} BERT`;$('bert-score-note').textContent=`${confidence} · ${bertFallbacks} fallback${bertFallbacks===1?'':'s'}`;}if(data.reason==='stale_result_discarded'||data.turn_id!==turnId)return;error(data.clarification||'');$('session-stats').textContent=`${data.stats.searches} searches · ${data.stats.cache_reuses} early candidate sets reused`;$('latency').textContent=`${data.latency_ms} ms`;$('input-state').textContent={wait:data.clarification?'Clarification needed':'Waiting for a stable request',provisional_retrieve:`Tentative · ${data.tentative_count} candidates`,commit_retrieve:'Final transcript committed',suppress:'Retrieval suppressed'}[data.decision];
 for(const id of ['stage-listen','stage-search','stage-verify','stage-answer'])$(id).classList.remove('active');const activeStage=$({wait:'stage-listen',provisional_retrieve:'stage-search',commit_retrieve:'stage-answer',suppress:'stage-answer'}[data.decision]);activeStage.classList.add('active');motion.stage(activeStage);
 $('intents').replaceChildren(...data.sub_queries.map((q,i)=>node('span','intent',`${i+1} · ${q.query}`)));motion.intents(Array.from($('intents').children));
 const correction=data.retrieval_events.find(e=>e.event_type==='transcript_normalized');if(correction){$('transcript-change').hidden=false;$('transcript-change').textContent=`Understood as: ${correction.payload.normalized_text}`;}
 if(data.answer!==null){$('version').textContent=`Version ${data.answer_version}`;renderClaims(data.claims,data.decision==='suppress'?[]:data.changed_claim_ids,false);if(data.presentation_items?.length){const list=node('ul','answer-bullets');for(const group of data.presentation_items){const item=node('li');for(const id of group.claim_ids){const claim=Array.from($('answer').children).find(e=>e.dataset.claimId===id);if(claim)item.append(claim);}list.append(item);}$('answer').replaceChildren(list);}const h=data.history.at(-1);if(h)$('version-history').textContent=`Version ${h.version} · ${h.added.length} added · ${h.replaced.length} replaced · ${h.preserved.length} preserved`;}
}
document.querySelectorAll('.scenario').forEach(button=>button.onclick=()=>{if(busy)return;selected=button.dataset.scenario;document.querySelectorAll('.scenario').forEach(b=>b.classList.toggle('selected',b===button));$('question').value=scenarios[selected].text;clearTimeout(debounce);partialQueue=null;$('transcript-change').hidden=true;newTurn();error('');});
$('question').value='';
$('question').addEventListener('input',()=>{clearTimeout(debounce);$('transcript-change').hidden=true;if(!busy&&$('question').value.trim())debounce=setTimeout(()=>queuePartial($('question').value),650);});
$('commit').onclick=async()=>{clearTimeout(debounce);partialQueue=null;busy=true;controls();try{await send($('question').value,true);}catch(e){error(e.message);}finally{busy=false;controls();}};
$('question').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('commit').click();}});
$('replay').onclick=async()=>{clearTimeout(debounce);busy=true;controls();error('');newTurn();const localEpoch=epoch;const s=scenarios[selected];$('input-hint').textContent='Simulated transcript replay · each prefix runs through the real engine.';try{for(let i=0;i<s.prefixes.length;i++){if(localEpoch!==epoch)return;const text=s.prefixes[i];$('question').value=text;await send(text,false,s.revision&&i===2?{revision_of:lastEvent}:{});await new Promise(resolve=>setTimeout(resolve,900));}if(localEpoch!==epoch)return;$('question').value=s.text;await send(s.text,true);if(s.followup){await new Promise(resolve=>setTimeout(resolve,1600));if(localEpoch!==epoch)return;newTurn();$('question').value=s.followup;await send(s.followup,true);}}catch(e){if(localEpoch===epoch)error(e.message);}finally{if(localEpoch===epoch){busy=false;controls();$('input-hint').textContent='Type naturally. Ctrl + Enter to ask.';}}};
$('bullets').onclick=async()=>{clearTimeout(debounce);partialQueue=null;busy=true;controls();try{newTurn();await send('Put that in bullets',true);}catch(e){error(e.message);}finally{busy=false;controls();}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({session_id:sessionId,corpus:uploadedCorpus?'Organizer session corpus':'Fictional LumaHome control',corpus_hash:corpusHash,events:audit},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='citefrontier-audit.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function clearWorkspace(){document.body.classList.remove('source-open');partialQueue=null;busy=false;bertEvents=bertServed=bertFallbacks=0;bertConfidence=[];$('bert-score').textContent='BERT active';$('bert-score-note').textContent='Waiting for transcript';$('question').value='';$('transcript-change').hidden=true;$('input-state').textContent='Ready when you are';$('session-stats').textContent='0 searches · 0 early candidate sets reused';$('version-history').textContent='';$('latency').textContent='— ms';error('');currentClaims=[];$('answer').replaceChildren(node('p','muted','New session. Play a transcript to begin.'));$('evidence').replaceChildren(node('p','muted','Select a committed citation to inspect its source.'));$('source-state').textContent='Awaiting selection';$('version').textContent='No committed answer';$('timeline').replaceChildren();$('intents').replaceChildren();$('answer-actions').hidden=true;}
$('reset').onclick=()=>{uploadedCorpus=false;clearWorkspace();$('organizer-score').textContent='Not run';$('organizer-score-note').textContent='Upload corpus + labeled questions';$('benchmark-details').replaceChildren();$('corpus-title').textContent='LumaHome control corpus';$('corpus-summary').textContent='10 fictional documents · 30 passages';$('corpus-footer').textContent='Fictional LumaHome corpus · official validation pending';$('corpus-dialog-note').textContent='Bundled fictional support documents.';$('question').placeholder='Ask about LumaHome products, warranties, setup or coverage…';connect();};
$('browse').onclick=async()=>{try{const response=await fetch(`/session/${sessionId}/corpus`,{headers:{Authorization:`Bearer ${sessionToken}`}});if(!response.ok)throw new Error('Could not load corpus');const corpus=await response.json();$('corpus-list').replaceChildren(...corpus.map(c=>{const row=node('div','corpus-row');row.append(node('strong','',c.chunk_id),node('p','',c.text));return row;}));$('corpus-dialog').showModal();motion.dialog($('corpus-dialog'));}catch(e){error(e.message);}};
$('close-corpus').onclick=()=>$('corpus-dialog').close();
$('scorecard').onclick=async()=>{try{const r=await fetch('/scorecard');if(!r.ok)throw new Error('Validation report unavailable');const data=await r.json();const root=$('validation-content');root.replaceChildren();if(uploadedCorpus)root.append(node('p','verified','Your uploaded corpus has not been benchmarked. The results below apply only to the bundled corpus.'));if(!data.cases){root.append(node('p','muted','Evaluation has not been run yet. Samsung validation remains pending.'));}else{root.append(node('p','',`${data.cases.passed} / ${data.cases.total} local acceptance scenarios passed`),node('p','muted',data.disclosure),node('p','muted',`Evaluated profile: ${data.configuration.backend} · ${data.configuration.parser}`));const table=node('table','score-table');for(const [name,result] of Object.entries(data.cases.categories)){const row=node('tr');row.append(node('th','',name.replaceAll('_',' ')),node('td','',`${result.passed} / ${result.total}`));table.append(row);}root.append(table);const m=data.metrics;const gates=node('table','score-table');const compound=data.cases.categories.compound;for(const [gate,score,target] of [['G2 · Early retrieval',`${m.early_retrieval.triggered}/${m.early_retrieval.eligible} (${(100*m.early_retrieval.rate).toFixed(1)}%)`,'≥80%'],['G3 · Multi-intent',`${compound.passed}/${compound.total} (${(100*compound.passed/compound.total).toFixed(1)}%)`,'≥70%'],['G4 · Citation support',`${m.attribution.supported}/${m.attribution.emitted} (${(100*m.attribution.rate).toFixed(1)}%); ${m.fabricated_ids.length} fabricated IDs`,'≥85%; zero fabricated IDs']]){const row=node('tr');row.append(node('th','',gate),node('td','',score),node('td','',target));gates.append(row);}root.prepend(node('h4','','G2–G4 · bundled corpus'),gates);root.append(node('p','muted',`Corpus hash: ${data.configuration.corpus_hash}. Dataset: evaluation/acceptance-v1.json. ATIS/SNIPS is not used for these gates.`));root.append(node('p','',`Answerable-intent coverage: ${m.intent_coverage.correct}/${m.intent_coverage.expected}. Extractive attribution: ${m.attribution.supported}/${m.attribution.emitted}.`),node('p','muted',`Warm endpoint p50 ${m.warm_endpoint_ms.p50.toFixed(1)} ms · p95 ${m.warm_endpoint_ms.p95.toFixed(1)} ms. Hardware and per-case records are in the downloadable audit reports.`),node('p','verified','Official Samsung corpus validation: pending.'));}$('validation-dialog').showModal();}catch(e){error(e.message);}};
$('close-validation').onclick=()=>$('validation-dialog').close();
// A single pending partial prevents rapid input changes from flooding the socket.
let partialQueue=null, partialSending=false;
async function queuePartial(text){
 if(!text.trim()||busy)return;
 if(ended)newTurn();
 partialQueue={text,epoch,turn:turnId};
 if(partialSending)return;
 partialSending=true;
 try{while(partialQueue){const item=partialQueue;partialQueue=null;if(item.epoch!==epoch||item.turn!==turnId||ended||busy)continue;try{await send(item.text);}catch(e){if(item.epoch===epoch)error(e.message);}}}finally{partialSending=false;}
}
$('view-toggle').onclick=()=>{const focus=document.body.classList.toggle('focus-mode');$('view-toggle').textContent=focus?'Show inspector':'Focus on conversation';$('view-toggle').setAttribute('aria-pressed',String(!focus));motion.inspector(!focus);};
$('copy-answer').onclick=async()=>{try{await navigator.clipboard.writeText(currentClaims.map(c=>`${c.text}${c.citations.length?' ['+c.citations.join('; ')+']':''}`).join('\n\n'));$('copy-answer').textContent='Copied with citations';setTimeout(()=>$('copy-answer').textContent='Copy answer with citations',1800);}catch(_){error('Clipboard unavailable. Select and copy the answer text instead.');}};
fetch('/demo-scenarios').then(r=>r.ok?r.json():{}).then(data=>{scenarios=data;controls();}).catch(()=>{scenarios={};controls();});
connect();

$('upload-open').onclick=()=>{$('upload-dialog').showModal();motion.dialog($('upload-dialog'));};
$('upload-close').onclick=()=>{if(!uploading)$('upload-dialog').close();};
$('upload-dialog').addEventListener('cancel',event=>{if(uploading)event.preventDefault();});
$('benchmark-file').addEventListener('change',controls);
$('benchmark-run').onclick=async()=>{try{const file=$('benchmark-file').files[0];if(!file)throw new Error('Choose a benchmark JSON file.');const cases=JSON.parse(await file.text());busy=true;controls();$('upload-status').textContent='Running labeled questions through the uploaded session corpus…';socket.send(JSON.stringify({type:'benchmark_run',cases}));}catch(e){busy=false;$('upload-status').textContent=e.message;controls();}};
$('upload-apply').onclick=async()=>{
 const files=Array.from($('corpus-files').files);if(!files.length||files.length>25){$('upload-status').textContent='Choose 1–25 source documents.';return;}
 if(files.reduce((n,f)=>n+f.size,0)>900000){$('upload-status').textContent='Choose files smaller than 900 KB combined (the wire limit is 1 MB).';return;}
 clearTimeout(debounce);partialQueue=null;busy=true;uploading=true;controls();$('upload-close').disabled=true;$('upload-status').textContent='Validating documents and building the session index…';
 try{const contents=await Promise.all(files.map(async f=>({name:f.name,text:await f.text()})));const message=JSON.stringify({type:'corpus_upload',files:contents});if(new TextEncoder().encode(message).length>1000000)throw new Error('Encoded upload exceeds 1 MB.');socket.send(message);uploadTimer=setTimeout(()=>{uploading=false;busy=false;socket.close();$('upload-status').textContent='Upload timed out. Start a new session and retry.';controls();$('upload-close').disabled=false;},60000);}catch(e){uploading=false;busy=false;$('upload-status').textContent=e.message;controls();}finally{$('upload-close').disabled=false;}
};
